{{ config(
            materialized='table',
                post_hook={
                    "sql": "create or replace table snitch_db.maplemonk.final_output_eoq as with main_data as ( select a.*,b.size_tag,c.xs_split,c.s_split,c.m_split,c.l_split,c.xl_split,c.xxl_split from snitch_db.maplemonk.repeat_order_quant_eoq a left join snitch_db.maplemonk.sku_group_xs_without_xs_eoq b on a.skU_group = b.sku_group left join snitch_db.maplemonk.category_size_split_xs_eoq c on a.category = c.category and b.size_tag = c.size_tag ), size_level_split as ( select *, ifnull((order_quantity*xs_split)::int,0) as xs_order_quant, ifnull((order_quantity*s_split)::int,0) as s_order_quant, ifnull((order_quantity*m_split)::int,0) as m_order_quant, ifnull((order_quantity*l_split)::int,0) as l_order_quant, ifnull((order_quantity*xl_split)::int,0) as xl_order_quant, ifnull((order_quantity*xxl_split)::int,0) as xxl_order_quant from main_data ), current_inv_pre as ( select sku_group, ifnull(sum(case when SIZE = \'XS\' OR SIZE = \'28\' then total_inventory end),0) as xs_inv, ifnull(sum(case WHEN SIZE = \'S\' OR SIZE = \'30\' then total_inventory end),0) as s_inv, ifnull(sum(case WHEN SIZE = \'M\' OR SIZE = \'32\' then total_inventory end),0) as m_inv, ifnull(sum(case WHEN SIZE = \'L\' OR SIZE = \'34\' then total_inventory end),0) as l_inv, ifnull(sum(case WHEN SIZE = \'XL\' OR SIZE = \'36\' then total_inventory end),0) as xl_inv, ifnull(sum(case when SIZE IN (\'XXL\', \'XXl\', \'2XL\', \'38\') then total_inventory end),0) as xxl_inv from snitch_db.maplemonk.cut_size_analysis where date = current_date-1 and sku_group in (select sku_group from snitch_db.maplemonk.repeat_decision_eoq where repeat = \'yes\') group by 1 union all select upper(trim(sku_group)) as sku_group, ifnull(sum(xs_units),0) as xs_inv, ifnull(sum(s_units),0) as s_inv, ifnull(sum(m_units),0) as m_inv, ifnull(sum(l_units),0) as l_inv, ifnull(sum(xl_units),0) as xl_inv, ifnull(sum(xxl_units),0) as xxl_inv from snitch_db.maplemonk.offline_master where upper(trim(sku_group)) in (select upper(trim(sku_group)) from snitch_db.maplemonk.repeat_decision_eoq where repeat = \'yes\') group by 1 ), current_inv as ( select sku_group, sum(xs_inv) as xs_inv, sum(s_inv) as s_inv, sum(m_inv) as m_inv, sum(l_inv) as l_inv, sum(xl_inv) as xl_inv, sum(xxl_inv) as xxl_inv from current_inv_pre group by 1 ), sales as ( select sku_group, ((ifnull(sum(case when size = \'XS\' then gross_quantity end),0)/30)*0.3)::int as xs_ros, (ifnull(sum(case when size = \'S\' then gross_quantity end),0)/30)::int as s_ros, (ifnull(sum(case when size = \'M\' then gross_quantity end),0)/30)::int as m_ros, (ifnull(sum(case when size = \'L\' then gross_quantity end),0)/30)::int as l_ros, (ifnull(sum(case when size = \'XL\' then gross_quantity end),0)/30)::int as xl_ros, ((ifnull(sum(case when size = \'XXL\' then gross_quantity end),0)/30)*0.3)::int as xxl_ros from snitch_db.maplemonk.horizontal_sales_categories where sku_group in (select sku_group from snitch_db.maplemonk.repeat_decision_eoq where repeat = \'yes\') and date >= current_date-30 group by 1 ), days_remaining as ( select sku_group, days_remaining from snitch_db.maplemonk.repeat_order_quant_eoq ), total_sales as ( select a.sku_group, xs_ros*b.days_remaining as xs_quant, s_ros*b.days_remaining as s_quant, m_ros*b.days_remaining as m_quant, l_ros*b.days_remaining as l_quant, xl_ros*b.days_remaining as xl_quant, xxl_ros*b.days_remaining as xxl_quant from sales a left join days_remaining b on a.sku_group = b.sku_group ), inv_subtraction as ( select a.sku_group, coalesce(greatest(xs_inv-xs_quant,0),0) as xs_remaining, coalesce(greatest(s_inv-s_quant,0),0) as s_remaining, coalesce(greatest(m_inv-m_quant,0),0) as m_remaining, coalesce(greatest(l_inv-l_quant,0),0) as l_remaining, coalesce(greatest(xl_inv-xl_quant,0),0) as xl_remaining, coalesce(greatest(xxl_inv-xxl_quant,0),0) as xxl_remaining, b.xxl_quant, a.xxl_inv, from current_inv a left join total_sales b on a.sku_group = b.sku_group ), final_output as ( select a.sku_group, a.final_ros, a.category, a.l1_category, a.actual_lead_time, a.repeat, a.seasonal, a.min_month, a.max_month, a.inward_date, a.flag, a.days_remaining, a.order_quantity, a.size_tag, a.xs_split, a.s_split, a.m_split, a.l_split, a.xl_split, a.xxl_split, coalesce(greatest(a.xs_order_quant-xs_remaining,0),0) as xs_order_quant, coalesce(greatest(a.s_order_quant-s_remaining,0),0) as s_order_quant, coalesce(greatest(a.m_order_quant-m_remaining,0),0) as m_order_quant, coalesce(greatest(a.l_order_quant-l_remaining,0),0) as l_order_quant, coalesce(greatest(a.xl_order_quant-xl_remaining,0),0) as xl_order_quant, coalesce(greatest(a.xxl_order_quant-xxl_remaining,0),0) as xxl_order_quant, case when repeat = \'no\' then 0 when category in (\'Bags\',\'Perfumes\') then order_quantity else coalesce(greatest(a.xs_order_quant-xs_remaining,0),0)+coalesce(greatest(a.s_order_quant-s_remaining,0),0)+ coalesce(greatest(a.m_order_quant-m_remaining,0),0)+coalesce(greatest(a.l_order_quant-l_remaining,0),0)+ coalesce(greatest(a.xl_order_quant-xl_remaining,0),0)+coalesce(greatest(a.xxl_order_quant-xs_remaining,0),0) end as revised_order_quant from size_level_split a left join inv_subtraction b on a.sku_group = b.sku_group ), images as ( SELECT split_part(t.id,\'/\',-1) AS product_id, image.value:\"preview\":\"image\":\"url\"::string AS image_url, ROW_NUMBER() OVER (PARTITION BY t.id ORDER BY image.index) AS image_rank FROM snitch_db.maplemonk.new_meafields_product_products_graph_ql t, LATERAL FLATTEN(input => parse_json(t.media)) AS image WHERE image.value:\"mediaContentType\"::string = \'IMAGE\' ), sku as ( select sku_group, product_name, category, id from snitch_db.maplemonk.availability_master_v2 qualify row_number() over (partition by sku_group order by status desc) = 1 ), sku_details as ( select a.*, category, sku_group, product_name from images a left join sku b on a.product_id::varchar = b.id::varchar where image_rank = 1 qualify row_number() over (partition by sku_group order by product_name) = 1 ), already_in_pipeline as ( select upper(trim(SUBSTRING(\"SKU\", 2))) AS sku_group, \'yes\' as production_pipeline from snitch_db.maplemonk.gs_rep_inw_repeat_list where lower(trim(status)) in (\'active\',\'fabric placed\',\'rts\') qualify row_number() over (partition by upper(trim(SUBSTRING(\"SKU\", 2))) order by date_issued desc)=1 ), metafields as ( select sku_group, occassion_new as occassion, print_design, collar_new as collar, designs, material_new as material, sleeve_type, fit, style, color from snitch_db.maplemonk.metafields_data qualify row_number() over (partition by sku_group order by status desc)=1 ), factory_suggestion as ( Select adjusted_sku as sku_group,factory_ from ( SELECT adjusted_sku, factory_, ROW_NUMBER() OVER (PARTITION BY ADJUSTED_SKU ORDER BY DATE DESC) AS RN FROM ( SELECT CASE WHEN \"SKU Number\" LIKE \'R%\' THEN SUBSTR(\"SKU Number\", 2) ELSE \"SKU Number\" END AS adjusted_sku, case when \"Factory Vendor Code\" in (\'01 - SSTC\', \'03 - Leandro\', \'13 - Kharva\', \'18 - Expert\', \'16 - Thandeshwara\', \'09 - Nalanda\', \'05 - Sai Textiles\', \'06 - Alagesh\', \'MQ - M Square\', \'14 - Lohith Creations\', \'IN - Mohit\', \'19 - S R Apparels\', \'Navkar\', \'02 - Kasturi Creation\', \'08 - Vignesh\', \'21-BLUE MONKEY\', \'KU - Kunal\', \'AC - Asian Clothing\', \'07 - K P\', \'15 - Prestige\', \'VN - Vanitha Garments\', \'10 - Adeep \') then \"Factory Vendor Code\" else factory end as factory_, TO_DATE(\"Date Issued\", \'DD-MM-YYYY\') AS DATE FROM snitch_db.maplemonk.PRODUCT_TRACKING_HIDDEN_SHIPPED UNION ALL Select CASE WHEN sku LIKE \'R%\' THEN SUBSTR(sku, 2) ELSE sku END AS adjusted_sku, factory_name, CASE WHEN TRY_TO_DATE(date_issued, \'DD-MM-YYYY\') IS NOT NULL THEN TO_DATE(date_issued, \'DD-MM-YYYY\') ELSE TO_DATE(date_issued, \'DD/MM/YYYY\') END AS DATE, from snitch_db.maplemonk.WORK_ORDERS_final_NEW_MAIN WHERE SKU_STATUS_ =\'Delivered\' and date_issued !=\'Delivered\' UNION ALL SELECT ADJUSTED_SKU, FACTORY_NAME, ISSUED_DATE FROM SNITCH_DB.MAPLEMONK.PRODUCTION_DATA WHERE STATUS = \'Delivered\' AND ISSUED_DATE IS NOT NULL ) ) sub WHERE RN = 1 ), selling_price as ( select sku_group, original_price, ifnull((offline_inventory+inventory),0) as current_inventory from snitch_db.maplemonk.product_journey qualify row_number() over (partition by sku_group order by original_price desc)=1 ), current_inv as ( select sku_group, sellable_inventory as current_inv, xs_units as current_xs, s_units as current_s, m_units as current_m, l_units as current_l, xl_units as current_xl, xxl_units as current_xxl from snitch_db.maplemonk.availability_master_v2 qualify row_number() over (partition by sku_group order by status desc) =1 ), size_production_ratio_pre as ( select sku_group, repeat, size_tag, revised_order_quant, category, CASE WHEN size_tag = \'with_xs_with_xxl\' THEN CAST( ARRAY_MIN(ARRAY_CONSTRUCT_COMPACT( NULLIF(xs_order_quant, 0), NULLIF(s_order_quant, 0), NULLIF(m_order_quant, 0), NULLIF(l_order_quant, 0), NULLIF(xl_order_quant, 0), NULLIF(xxl_order_quant, 0) )) AS INTEGER) WHEN size_tag = \'without_xs_without_xxl\' THEN CAST( ARRAY_MIN(ARRAY_CONSTRUCT_COMPACT( NULLIF(s_order_quant, 0), NULLIF(m_order_quant, 0), NULLIF(l_order_quant, 0), NULLIF(xl_order_quant, 0) )) AS INTEGER) WHEN size_tag = \'with_xs_without_xxl\' THEN CAST( ARRAY_MIN(ARRAY_CONSTRUCT_COMPACT( NULLIF(xs_order_quant, 0), NULLIF(s_order_quant, 0), NULLIF(m_order_quant, 0), NULLIF(l_order_quant, 0), NULLIF(xl_order_quant, 0) )) AS INTEGER) WHEN size_tag = \'without_xs_with_xxl\' THEN CAST( ARRAY_MIN(ARRAY_CONSTRUCT_COMPACT( NULLIF(s_order_quant, 0), NULLIF(m_order_quant, 0), NULLIF(l_order_quant, 0), NULLIF(xl_order_quant, 0), NULLIF(xxl_order_quant, 0) )) AS INTEGER) END AS least_quant from final_output where repeat = \'yes\' ), size_production_ratio_pre2 as ( select a.sku_group, a.repeat, a.size_tag, a.revised_order_quant, a.category, xs_order_quant/least_quant as xs_ratio , s_order_quant/least_quant as s_ratio, l_order_quant/least_quant as l_ratio, m_order_quant/least_quant as m_ratio, xl_order_quant/least_quant as xl_ratio, xxl_order_quant/least_quant as xxl_ratio from final_output a left join size_production_ratio_pre b on a.sku_group = b.sku_group where a.repeat = \'yes\' ), size_production_ratio as ( select sku_group, concat(round(xs_ratio,1),\' : \',round(s_ratio,1),\' : \',round(m_ratio,1),\' : \',round(l_ratio,1),\' : \',round(xl_ratio,1),\' : \',round(xxl_ratio,1)) as size_ratio from size_production_ratio_pre2 ), returns_percentage as ( select upper(trim(sku_group)) as sku_group, div0(sum(return_qty),sum(sales_qty)) as return_percentage from snitch_db.maplemonk.return_fact_items group by 1 ), fabric_source as ( SELECT upper(trim(sku)) as sku_group, fabric_origin FROM SNITCH_DB.MAPLEMONK.FABRIC_SOURCE ), exlusion_list as ( select upper(trim(sku_group)) as sku_group, \'yes\' as exclusion_tag from snitch_db.maplemonk.gs_skulist qualify row_number() over (partition by upper(trim(sku_group)) order by remarks desc) =1 ), nos as ( SELECT sku_group, tag as nos_tag FROM SNITCH_DB.MAPLEMONK.NOOS_LIST_CHANNEL_WISE ), overall_sales as ( select sku_group, ifnull(sum(case when type = \'Shopify\' then gross_quantity end),0) as shopify_overall_sales_quant, ifnull(sum(case when type = \'Marketplace\' then gross_quantity end),0) as mp_overall_sales_quant, ifnull(sum(case when type = \'Store\' and channel <> \'SNITCH - MARKET PLACE - SLIKK\' then gross_quantity end),0) as store_overall_sales_quant, from snitch_db.maplemonk.horizontal_sales_categories group by 1 ) select a.*, b.product_name as title, b.image_url as preview_image, case when c.nos_tag in (\'Offline\',\'Online\') then \'yes\' else \'no\' end as nos_flag, coalesce(d.production_pipeline,\'no\') as production_pipeline, occassion, print_design, collar, designs, material, sleeve_type, fit, style, color, f.factory_ as factory, g.original_price as mrp, g.current_inventory, h.size_ratio, i.return_percentage, j.fabric_origin, k.exclusion_tag, l.shopify_overall_sales_quant, l.mp_overall_sales_quant, l.store_overall_sales_quant from final_output a left join sku_details b on a.sku_group = b.sku_group left join nos c on a.sku_group = c.sku_group left join already_in_pipeline d on a.sku_group = d.sku_group left join metafields e on a.sku_group = e.sku_group left join factory_suggestion f on a.sku_group = f.sku_group left join selling_price g on a.sku_group = g.sku_group left join size_production_ratio h on a.sku_group = h.sku_group left join returns_percentage i on a.sku_group = i.sku_group left join fabric_source j on a.sku_group = j.sku_group left join exlusion_list k on a.sku_group = k.sku_group left join overall_sales l on a.sku_group = l.sku_group ;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from snitch_db.information_schema.databases
            ),
            
            final as (
                select * from sample_data
